from collections import deque

def count_4connected_components(colors):
    H = len(colors)
    W = len(colors[0])
    visited = [[False]*W for _ in range(H)]
    comp_count = {}

    def bfs(r, c, color):
        q = deque([(r,c)])
        visited[r][c] = True
        print(f"  Starting BFS from ({r},{c}) for color {color}")
        while q:
            x, y = q.popleft()
            for dx, dy in [(0,-1),(0,1),(-1,0),(1,0)]:
                nx, ny = x+dx, y+dy
                if 0 <= nx < H and 0 <= ny < W:
                    if not visited[nx][ny] and colors[nx][ny] == color:
                        visited[nx][ny] = True
                        q.append((nx, ny))

    for i in range(H):
        for j in range(W):
            if not visited[i][j] and colors[i][j] != 0:
                color = colors[i][j]
                bfs(i,j,color)
                comp_count[color] = comp_count.get(color, 0) + 1

    return comp_count

