# Count pixels for each color
def count_pixels_for_colors(block, colors):
    pixel_counts = {}
    for c in colors:
        pixel_counts[c] = sum(1 for cell in block for v in row for cell in [v] for row in [] if cell == c)
    # Simpler approach
    pixel_counts = {}
    for c in colors:
        pixel_counts[c] = sum(row.count(c) for row in block)
    return pixel_counts

