print("=== ANALYZING TIE CASES IN DEMOS ===")

def analyze_tie_cases():
    tie_cases = []
    for br in range(6):
        for bc in range(6):
            start_r, start_c = br * 3, bc * 3

            block = []
            flat_vals = []
            for dr in range(3):
                blk_row = demos_input[start_r + dr][start_c:start_c+3]
                block.append(blk_row)
                flat_vals.extend(blk_row)

            unique_colors = sorted(set(c for c in flat_vals if c != 0))

            if len(unique_colors) > 1:
                comps = count_4connected_components(block)

                max_comps = max(comps.values())
                max_comp_colors = [c for c, n in comps.items() if n == max_comps]

                if len(max_comp_colors) > 1:
                    target = expected_demo[br][bc]

                    print(f"\nTIE case [{br},{bc}] -> target={target}")
                    print(f"  Block:\n{block}")
                    print(f"  Colors: {unique_colors}")
                    print(f"  Comps: {dict(comps)}")

                    # Pixel counts
                    pixel_counts = {}
                    for c in unique_colors:
                        pixel_counts[c] = sum(row.count(c) for row in block)
                    print(f"  Pixels: {pixel_counts}")

                    # What does each tiebreaker give?
                    min_val = min(unique_colors)
                    max_val = max(unique_colors)
                    min_comp = min(unique_colors)
                    max_comp = max(unique_colors)

                    # Find winner under various rules
                    def find_winner(comps_dict, pixel_dict, criterion):
                        candidates = [c for c, n in comps_dict.items() if n == max(comps_dict.values())]
                        if criterion == 'min_color':
                            return min(candidates)
                        elif criterion == 'max_color':
                            return max(candidates)
                        elif criterion == 'max_pixel':
                            return max(candidates, key=lambda x: pixel_dict[x])
                        elif criterion == 'min_pixel':
                            return min(candidates, key=lambda x: pixel_dict[x])
                        else:
                            return min(candidates)

                    print(f"  min_color: {find_winner(comps, pixel_counts, 'min_color')}")
                    print(f"  max_color: {find_winner(comps, pixel_counts, 'max_color')}")
                    print(f"  max_pixel: {find_winner(comps, pixel_counts, 'max_pixel')}")
                    print(f"  min_pixel: {find_winner(comps, pixel_counts, 'min_pixel')}")

                    tie_cases.append({
                        'pos': f"[{br},{bc}]",
                        'target': target,
                        'colors': unique_colors,
                        'comps': dict(comps),
                        'pixels': pixel_counts,
                        'min_color': min_val,
                        'max_color': max_val
                    })

    return tie_cases

tie_cases = analyze_tie_cases()

